mapper.select:
SELECT * FROM oa_supplier_score_criteria
WHERE scorecard_id = #{scorecardId} AND tenant_id = #{tenantId}
FOR UPDATE

mapper.update:
UPDATE oa_supplier_score_criteria
SET criteria_name = #{item.criteriaName}, weight = #{item.weight}, score = #{item.score},
    max_score = #{item.maxScore}, data_source = #{item.dataSource}, auto_value = #{item.autoValue},
    remark = #{item.remark}, deleted = 0, update_by = #{item.updateBy}, update_time = #{item.updateTime}
WHERE criteria_id = #{item.criteriaId} AND tenant_id = #{item.tenantId}
  AND scorecard_id = #{item.scorecardId} AND criteria_code = #{item.criteriaCode} AND deleted = 1
  AND EXISTS (SELECT 1 FROM oa_supplier_scorecard card
              WHERE card.scorecard_id = #{item.scorecardId} AND card.tenant_id = #{item.tenantId}
                AND card.status = 'DRAFT' AND card.deleted = 0)
